Here is a complete, interactive HTML mockup of the Sovereign app UI. It demonstrates the dark‑first, modular dashboard with hidden power tools, following the design system we built together.

All components are self‑contained in a single file – you can open it in any browser to see the look, feel, and basic interactions.

---

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no" />
  <title>Sovereign — Privacy‑First Daily OS</title>

  <!-- Google Fonts (Inter + JetBrains Mono) -->
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700&family=JetBrains+Mono:wght@400;600&display=swap" rel="stylesheet" />

  <!-- Feather Icons (via CDN for demo) -->
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css" />

  <style>
    /* ---------- RESET & BASE ---------- */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      --bg-base: #0A0A0F;
      --bg-surface: #12121A;
      --bg-card: #1A1A26;
      --bg-card-hover: #222236;
      --text-primary: #F0F0F5;
      --text-secondary: #8A8A9E;
      --text-muted: #5A5A72;
      --accent-primary: #6C5CE7;
      --accent-secondary: #00CEC9;
      --accent-gradient: linear-gradient(135deg, #6C5CE7, #A29BFE);
      --glass-bg: rgba(26, 26, 38, 0.7);
      --glass-border: rgba(255,255,255,0.05);
      --shadow: 0 8px 32px rgba(0,0,0,0.6);
      --radius-card: 16px;
      --radius-btn: 12px;
      --radius-fab: 28px;
      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    body {
      font-family: 'Inter', -apple-system, sans-serif;
      background: var(--bg-base);
      color: var(--text-primary);
      height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 12px;
      user-select: none;
    }

    /* ---------- PHONE FRAME ---------- */
    .phone {
      width: 380px;
      max-width: 100%;
      height: 780px;
      max-height: 95vh;
      background: var(--bg-surface);
      border-radius: 42px;
      padding: 12px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.8), inset 0 0 0 1px rgba(255,255,255,0.06);
      position: relative;
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    /* ---------- STATUS BAR (fake) ---------- */
    .status-bar {
      display: flex;
      justify-content: space-between;
      padding: 4px 8px 8px 8px;
      font-size: 12px;
      color: var(--text-secondary);
      letter-spacing: 0.3px;
      flex-shrink: 0;
    }
    .status-bar .time {
      font-weight: 600;
    }
    .status-bar .icons i {
      margin-left: 4px;
      font-size: 13px;
    }

    /* ---------- TOP BAR ---------- */
    .top-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 4px 0 12px 0;
      flex-shrink: 0;
    }
    .top-bar .left {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .top-bar .left .hamburger {
      font-size: 22px;
      color: var(--text-primary);
      cursor: pointer;
      transition: var(--transition);
      padding: 4px;
    }
    .top-bar .left .hamburger:hover {
      color: var(--accent-primary);
    }
    .top-bar .left .app-title {
      font-weight: 700;
      font-size: 18px;
      letter-spacing: -0.3px;
      background: var(--accent-gradient);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
    }
    .top-bar .right {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .top-bar .right i {
      font-size: 18px;
      color: var(--text-secondary);
      cursor: pointer;
      transition: var(--transition);
    }
    .top-bar .right i:hover {
      color: var(--text-primary);
    }

    /* ---------- MAIN CONTENT (scrollable) ---------- */
    .main-content {
      flex: 1;
      overflow-y: auto;
      padding: 0 2px 8px 2px;
      scrollbar-width: thin;
      scrollbar-color: var(--bg-card) transparent;
    }
    .main-content::-webkit-scrollbar {
      width: 4px;
    }
    .main-content::-webkit-scrollbar-track {
      background: transparent;
    }
    .main-content::-webkit-scrollbar-thumb {
      background: var(--bg-card);
      border-radius: 8px;
    }

    /* ---------- GREETING ---------- */
    .greeting {
      margin-bottom: 20px;
    }
    .greeting h2 {
      font-size: 20px;
      font-weight: 600;
      margin-bottom: 4px;
    }
    .greeting h2 span {
      background: var(--accent-gradient);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
    }
    .greeting p {
      color: var(--text-secondary);
      font-size: 14px;
    }

    /* ---------- WIDGET GRID ---------- */
    .widget-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
      margin-bottom: 16px;
    }
    .widget-card {
      background: var(--bg-card);
      border-radius: var(--radius-card);
      padding: 16px;
      border: 1px solid var(--glass-border);
      box-shadow: var(--shadow);
      transition: var(--transition);
      cursor: default;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }
    .widget-card:hover {
      background: var(--bg-card-hover);
      transform: translateY(-2px);
    }
    .widget-card .card-header {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .widget-card .card-header i {
      font-size: 20px;
      color: var(--accent-primary);
    }
    .widget-card .card-header .card-title {
      font-weight: 600;
      font-size: 14px;
      color: var(--text-primary);
    }
    .widget-card .card-content {
      font-size: 13px;
      color: var(--text-secondary);
      line-height: 1.5;
    }
    .widget-card .card-footer {
      margin-top: auto;
      padding-top: 8px;
      border-top: 1px solid rgba(255,255,255,0.04);
      font-size: 12px;
      color: var(--text-muted);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .widget-card .card-footer .badge {
      background: rgba(108,92,231,0.15);
      color: var(--accent-primary);
      padding: 2px 8px;
      border-radius: 20px;
      font-size: 11px;
    }
    .widget-card .card-footer .action {
      color: var(--accent-secondary);
      font-weight: 500;
      cursor: pointer;
      font-size: 13px;
    }
    .widget-card .card-footer .action:hover {
      text-decoration: underline;
    }

    /* full-width widgets */
    .widget-full {
      grid-column: 1 / -1;
    }

    /* ---------- RECENT FILES LIST ---------- */
    .file-list {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-top: 4px;
    }
    .file-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 13px;
      color: var(--text-secondary);
      padding: 4px 0;
      border-bottom: 1px solid rgba(255,255,255,0.03);
    }
    .file-item .name {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .file-item .name i {
      color: var(--accent-primary);
      font-size: 14px;
    }
    .file-item .size {
      color: var(--text-muted);
      font-size: 12px;
    }

    /* ---------- BOTTOM NAV ---------- */
    .bottom-nav {
      display: flex;
      justify-content: space-around;
      align-items: center;
      padding: 8px 12px 12px 12px;
      background: var(--bg-surface);
      border-top: 1px solid rgba(255,255,255,0.04);
      flex-shrink: 0;
      position: relative;
    }
    .nav-item {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 2px;
      color: var(--text-secondary);
      font-size: 11px;
      cursor: pointer;
      transition: var(--transition);
      padding: 4px 8px;
      border-radius: 8px;
      position: relative;
    }
    .nav-item i {
      font-size: 20px;
      transition: var(--transition);
    }
    .nav-item.active {
      color: var(--accent-primary);
    }
    .nav-item.active i {
      color: var(--accent-primary);
    }
    .nav-item.active::after {
      content: '';
      position: absolute;
      bottom: -6px;
      left: 50%;
      transform: translateX(-50%);
      width: 6px;
      height: 6px;
      background: var(--accent-primary);
      border-radius: 50%;
    }
    .nav-item:hover {
      color: var(--text-primary);
    }

    /* ---------- FAB ---------- */
    .fab-container {
      position: absolute;
      bottom: 80px;
      right: 24px;
      z-index: 10;
    }
    .fab {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-fab);
      background: var(--accent-gradient);
      box-shadow: 0 4px 20px rgba(108,92,231,0.4);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #fff;
      font-size: 28px;
      cursor: pointer;
      transition: var(--transition);
      border: none;
      outline: none;
    }
    .fab:hover {
      transform: scale(1.05);
      box-shadow: 0 6px 30px rgba(108,92,231,0.6);
    }
    .fab:active {
      transform: scale(0.92);
    }

    /* Radial menu (hidden by default) */
    .radial-menu {
      position: absolute;
      bottom: 70px;
      right: 10px;
      background: var(--bg-card);
      border-radius: 20px;
      padding: 12px 8px;
      box-shadow: 0 8px 40px rgba(0,0,0,0.8);
      border: 1px solid var(--glass-border);
      display: none;
      flex-direction: column;
      gap: 4px;
      min-width: 140px;
      backdrop-filter: blur(12px);
    }
    .radial-menu.open {
      display: flex;
    }
    .radial-menu .menu-item {
      padding: 8px 14px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 14px;
      color: var(--text-secondary);
      cursor: pointer;
      transition: var(--transition);
    }
    .radial-menu .menu-item i {
      width: 20px;
      color: var(--accent-primary);
    }
    .radial-menu .menu-item:hover {
      background: rgba(108,92,231,0.1);
      color: var(--text-primary);
    }

    /* ---------- DRAWER (sidebar) ---------- */
    .drawer-overlay {
      position: absolute;
      inset: 0;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(4px);
      z-index: 20;
      display: none;
      border-radius: 42px;
    }
    .drawer-overlay.open {
      display: block;
    }
    .drawer {
      position: absolute;
      top: 0;
      left: 0;
      bottom: 0;
      width: 280px;
      background: var(--bg-surface);
      border-radius: 42px 0 0 42px;
      padding: 24px 16px;
      transform: translateX(-100%);
      transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: 4px 0 30px rgba(0,0,0,0.8);
      overflow-y: auto;
      border-right: 1px solid var(--glass-border);
    }
    .drawer-overlay.open .drawer {
      transform: translateX(0);
    }
    .drawer .drawer-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 24px;
    }
    .drawer .drawer-header .close {
      font-size: 24px;
      cursor: pointer;
      color: var(--text-secondary);
    }
    .drawer .drawer-header .close:hover {
      color: var(--text-primary);
    }
    .drawer .section-title {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin: 16px 0 8px 0;
    }
    .drawer .drawer-item {
      padding: 10px 12px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      gap: 14px;
      font-size: 15px;
      color: var(--text-secondary);
      cursor: pointer;
      transition: var(--transition);
    }
    .drawer .drawer-item i {
      width: 22px;
      color: var(--text-muted);
    }
    .drawer .drawer-item:hover {
      background: rgba(108,92,231,0.08);
      color: var(--text-primary);
    }
    .drawer .drawer-item.active {
      color: var(--text-primary);
      background: rgba(108,92,231,0.12);
    }
    .drawer .drawer-item.active i {
      color: var(--accent-primary);
    }
    .drawer .power-tools {
      margin-top: 8px;
      border-top: 1px solid rgba(255,255,255,0.05);
      padding-top: 8px;
    }
    .drawer .power-tools .drawer-item {
      color: var(--text-muted);
      font-size: 14px;
      opacity: 0.6;
      cursor: not-allowed;
    }
    .drawer .power-tools .drawer-item i {
      color: var(--text-muted);
    }
    .drawer .power-tools .drawer-item.enabled {
      opacity: 1;
      cursor: pointer;
      color: var(--text-secondary);
    }
    .drawer .power-tools .drawer-item.enabled i {
      color: var(--accent-secondary);
    }
    .drawer .power-toggle {
      background: rgba(108,92,231,0.1);
      border-radius: 10px;
      padding: 12px;
      margin-top: 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .drawer .power-toggle span {
      font-size: 13px;
      color: var(--text-secondary);
    }
    .drawer .power-toggle .switch {
      width: 40px;
      height: 22px;
      background: var(--bg-card);
      border-radius: 12px;
      position: relative;
      cursor: pointer;
      transition: var(--transition);
      border: 1px solid var(--glass-border);
    }
    .drawer .power-toggle .switch.on {
      background: var(--accent-primary);
    }
    .drawer .power-toggle .switch .knob {
      width: 18px;
      height: 18px;
      background: #fff;
      border-radius: 50%;
      position: absolute;
      top: 1px;
      left: 1px;
      transition: var(--transition);
    }
    .drawer .power-toggle .switch.on .knob {
      left: 19px;
    }

    /* ---------- RESPONSIVE ---------- */
    @media (max-width: 420px) {
      .phone {
        border-radius: 28px;
        padding: 8px;
        height: 95vh;
      }
      .drawer {
        width: 240px;
      }
      .widget-grid {
        gap: 10px;
      }
      .widget-card {
        padding: 12px;
      }
    }
  </style>
</head>
<body>

  <div class="phone" id="app">

    <!-- Status Bar -->
    <div class="status-bar">
      <span class="time">9:41</span>
      <span class="icons">
        <i class="fas fa-signal"></i>
        <i class="fas fa-wifi"></i>
        <i class="fas fa-battery-three-quarters"></i>
      </span>
    </div>

    <!-- Top Bar -->
    <div class="top-bar">
      <div class="left">
        <span class="hamburger" id="hamburgerBtn"><i class="fas fa-bars"></i></span>
        <span class="app-title">Sovereign</span>
      </div>
      <div class="right">
        <i class="fas fa-search"></i>
        <i class="fas fa-ellipsis-v"></i>
      </div>
    </div>

    <!-- Main Content -->
    <div class="main-content" id="mainContent">
      <!-- Greeting -->
      <div class="greeting">
        <h2>Good Morning, <span>User</span> 👋</h2>
        <p>You have 3 tasks today</p>
      </div>

      <!-- Widget Grid -->
      <div class="widget-grid">
        <!-- Quick Notes -->
        <div class="widget-card">
          <div class="card-header">
            <i class="fas fa-pen-fancy"></i>
            <span class="card-title">Quick Notes</span>
          </div>
          <div class="card-content">
            • Meeting notes<br>
            • Grocery list<br>
            • Project ideas
          </div>
          <div class="card-footer">
            <span class="badge">3 items</span>
            <span class="action">+ New</span>
          </div>
        </div>

        <!-- Quick Tasks -->
        <div class="widget-card">
          <div class="card-header">
            <i class="fas fa-check-circle"></i>
            <span class="card-title">Quick Tasks</span>
          </div>
          <div class="card-content">
            • Buy groceries<br>
            • Call client<br>
            • Review design
          </div>
          <div class="card-footer">
            <span class="badge">2 pending</span>
            <span class="action">+ Add</span>
          </div>
        </div>

        <!-- Vault -->
        <div class="widget-card">
          <div class="card-header">
            <i class="fas fa-lock"></i>
            <span class="card-title">Vault</span>
          </div>
          <div class="card-content">
            🔑 Google Account<br>
            💳 ICICI Bank<br>
            🆘 Emergency Info
          </div>
          <div class="card-footer">
            <span class="badge">12 items</span>
            <span class="action">Unlock</span>
          </div>
        </div>

        <!-- Scanner -->
        <div class="widget-card">
          <div class="card-header">
            <i class="fas fa-camera"></i>
            <span class="card-title">Scanner</span>
          </div>
          <div class="card-content">
            📄 5 scans this week<br>
            🧾 Receipts, Aadhaar
          </div>
          <div class="card-footer">
            <span class="badge">Ready</span>
            <span class="action">Scan</span>
          </div>
        </div>

        <!-- Clipboard History (full width) -->
        <div class="widget-card widget-full">
          <div class="card-header">
            <i class="fas fa-clipboard"></i>
            <span class="card-title">Clipboard History</span>
          </div>
          <div class="card-content">
            <div class="file-list">
              <div class="file-item"><span class="name"><i class="fas fa-file-alt"></i> Meeting notes draft</span><span class="size">2 min ago</span></div>
              <div class="file-item"><span class="name"><i class="fas fa-link"></i> https://github.com/...</span><span class="size">15 min ago</span></div>
              <div class="file-item"><span class="name"><i class="fas fa-code"></i> const API_KEY = ...</span><span class="size">1 hour ago</span></div>
            </div>
          </div>
          <div class="card-footer">
            <span class="badge">5 items</span>
            <span class="action">Clear</span>
          </div>
        </div>

        <!-- Recent Files (full width) -->
        <div class="widget-card widget-full">
          <div class="card-header">
            <i class="fas fa-folder-open"></i>
            <span class="card-title">Recent Files</span>
          </div>
          <div class="card-content">
            <div class="file-list">
              <div class="file-item"><span class="name"><i class="fas fa-file-pdf"></i> Invoice_Aug_2026.pdf</span><span class="size">2.4 MB</span></div>
              <div class="file-item"><span class="name"><i class="fas fa-file-alt"></i> Note_26-08-26.md</span><span class="size">12 KB</span></div>
              <div class="file-item"><span class="name"><i class="fas fa-archive"></i> Vault_Backup_Aug.vault</span><span class="size">8.7 MB</span></div>
            </div>
          </div>
          <div class="card-footer">
            <span class="badge">8 files</span>
            <span class="action">View All</span>
          </div>
        </div>
      </div>
    </div>

    <!-- Bottom Navigation -->
    <div class="bottom-nav">
      <div class="nav-item active" data-tab="home"><i class="fas fa-home"></i><span>Home</span></div>
      <div class="nav-item" data-tab="files"><i class="fas fa-folder"></i><span>Files</span></div>
      <div class="nav-item" data-tab="vault"><i class="fas fa-lock"></i><span>Vault</span></div>
      <div class="nav-item" data-tab="more"><i class="fas fa-cog"></i><span>More</span></div>
    </div>

    <!-- FAB + Radial Menu -->
    <div class="fab-container">
      <div class="fab" id="fabBtn"><i class="fas fa-plus"></i></div>
      <div class="radial-menu" id="radialMenu">
        <div class="menu-item"><i class="fas fa-pen"></i> New Note</div>
        <div class="menu-item"><i class="fas fa-camera"></i> Scan Document</div>
        <div class="menu-item"><i class="fas fa-key"></i> Add Password</div>
        <div class="menu-item"><i class="fas fa-check"></i> New Task</div>
      </div>
    </div>

    <!-- Drawer (Sidebar) -->
    <div class="drawer-overlay" id="drawerOverlay">
      <div class="drawer">
        <div class="drawer-header">
          <span style="font-weight:600; font-size:18px;">Sovereign</span>
          <span class="close" id="closeDrawer"><i class="fas fa-times"></i></span>
        </div>

        <div class="section-title">Personal</div>
        <div class="drawer-item active"><i class="fas fa-home"></i> Home</div>
        <div class="drawer-item"><i class="fas fa-pen-fancy"></i> Notes</div>
        <div class="drawer-item"><i class="fas fa-lock"></i> Vault</div>
        <div class="drawer-item"><i class="fas fa-check-circle"></i> Tasks</div>
        <div class="drawer-item"><i class="fas fa-camera"></i> Scanner</div>
        <div class="drawer-item"><i class="fas fa-archive"></i> Backup &amp; Sync</div>

        <div class="power-tools">
          <div class="section-title" style="margin-top:0;">Power Tools</div>
          <div class="drawer-item" id="aiItem"><i class="fas fa-robot"></i> AI Model Hub</div>
          <div class="drawer-item" id="terminalItem"><i class="fas fa-terminal"></i> Terminal Bridge</div>
          <div class="drawer-item" id="pluginItem"><i class="fas fa-plug"></i> Plugin Manager</div>
          <div class="drawer-item" id="scriptItem"><i class="fas fa-code"></i> Script Scheduler</div>

          <div class="power-toggle">
            <span>Developer Mode</span>
            <div class="switch" id="devModeSwitch">
              <div class="knob"></div>
            </div>
          </div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:8px; text-align:center;">
            Tap version 7 times in Settings to unlock
          </div>
        </div>
      </div>
    </div>

  </div>

  <script>
    // ---------- INTERACTIONS ----------
    const hamburgerBtn = document.getElementById('hamburgerBtn');
    const drawerOverlay = document.getElementById('drawerOverlay');
    const closeDrawer = document.getElementById('closeDrawer');
    const fabBtn = document.getElementById('fabBtn');
    const radialMenu = document.getElementById('radialMenu');
    const devSwitch = document.getElementById('devModeSwitch');
    const powerItems = document.querySelectorAll('.power-tools .drawer-item');

    // Open drawer
    hamburgerBtn.addEventListener('click', () => {
      drawerOverlay.classList.add('open');
    });

    // Close drawer (overlay click or close button)
    drawerOverlay.addEventListener('click', (e) => {
      if (e.target === drawerOverlay || e.target === closeDrawer) {
        drawerOverlay.classList.remove('open');
      }
    });

    // FAB toggle radial menu
    fabBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      radialMenu.classList.toggle('open');
    });

    // Close radial menu when clicking elsewhere
    document.addEventListener('click', (e) => {
      if (!fabBtn.contains(e.target) && !radialMenu.contains(e.target)) {
        radialMenu.classList.remove('open');
      }
    });

    // Developer Mode toggle (simulate)
    devSwitch.addEventListener('click', () => {
      devSwitch.classList.toggle('on');
      const enabled = devSwitch.classList.contains('on');
      powerItems.forEach(item => {
        item.classList.toggle('enabled', enabled);
        if (enabled) {
          item.style.opacity = '1';
          item.style.cursor = 'pointer';
        } else {
          item.style.opacity = '0.6';
          item.style.cursor = 'not-allowed';
        }
      });
    });

    // Bottom nav click (just highlight)
    document.querySelectorAll('.nav-item').forEach(item => {
      item.addEventListener('click', () => {
        document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
        item.classList.add('active');
      });
    });

    // Demo: drawer item click - close drawer and show alert
    document.querySelectorAll('.drawer-item:not(.power-tools .drawer-item)').forEach(item => {
      item.addEventListener('click', () => {
        drawerOverlay.classList.remove('open');
        // optional: show which section (for demo)
        const text = item.textContent.trim();
        if (text) {
          // update greeting or something?
          const greeting = document.querySelector('.greeting h2 span');
          greeting.textContent = text;
        }
      });
    });

    // Power items (only when enabled) - demo
    powerItems.forEach(item => {
      item.addEventListener('click', () => {
        if (item.classList.contains('enabled')) {
          alert(`🔧 Power Tool: ${item.textContent.trim()} activated!\n(Simulated)`);
          drawerOverlay.classList.remove('open');
        }
      });
    });

    // Extra: tap version number 7 times (simulated) – we'll just show a message
    let tapCount = 0;
    document.querySelector('.power-toggle div:last-child')?.addEventListener('dblclick', () => {
      // Not needed, just for demo
    });

    // Also clicking on the "Tap version 7 times..." text can toggle dev mode (for demo)
    document.querySelector('.power-toggle div:last-child')?.addEventListener('click', () => {
